const scenarios={assembly:['Montaje libre','Free assembly'],healthy:['Cadena conectada · sin falla','Connected chain · no fault'],F1:['Sin alimentación al EM','No EM power'],F2:['EM trabado','EM locked up'],F3:['EM dañado tras reinicio','EM fault persists after reboot'],F4:['Conector medio sin asegurar','Middle connector unsecured'],F5:['Rosca del EM a medio apretar','EM thread partially tightened'],F6:['Cable café suelto','Loose brown terminal'],F7:['Cable naranja suelto','Loose orange terminal'],F8:['Arnés dañado','Damaged harness'],F9:['Pantalla defectuosa','Faulty screen'],F10:['Pantalla sin positivo conmutado','Screen missing key switched positive'],F11:['Pantalla sin tierra','Screen missing ground'],F12:['Naranja en pin 12 del EM','Orange wire at EM pin 12']};
function updateLabels(){document.documentElement.lang=lang;$('lang').innerHTML=lang==='es'?'ES <span>/ EN</span>':'<span>ES /</span> EN';$('hitboxes').textContent=hitboxesVisible?tr('Ocultar hitboxes','Hide hitboxes'):tr('Mostrar hitboxes','Show hitboxes');$('controlsText').textContent=tr('Puntas: acercar y pulsar Conectar punta · Conectores: acercar y pulsar Conectar · Rueda: profundidad','Probes: approach and press Connect probe · Connectors: approach and press Connect · Wheel: depth');$('modeLabel').textContent=tr('CONEXIÓN & DIAGNÓSTICO','CONNECTION & DIAGNOSTICS');$('instructorHint').textContent=tr('I · Instructor','I · Instructor');$('setupTitle').textContent=tr('Preparar práctica','Set up training');$('setupIntro').textContent=tr('Selecciona el escenario antes de entregar el simulador al interno. La falla no se muestra durante la práctica.','Select a scenario before handing the simulator to the trainee. The fault is hidden during practice.');$('scenarioLabel').textContent=tr('Escenario','Scenario');const old=$('scenario').value||'assembly';$('scenario').replaceChildren(...Object.entries(scenarios).map(([code,text])=>{const o=document.createElement('option');o.value=code;o.textContent=(code.startsWith('F')?code+' · ':'')+text[lang==='es'?0:1];return o;}));$('scenario').value=old;$('segmentLabel').textContent=tr('Tramo afectado','Affected segment');$('segment').options[0].text=tr('Arnés superior','Upper harness');$('segment').options[1].text=tr('Arnés inferior','Lower harness');$('closeSetup').textContent=tr('Volver','Back');$('startScenario').textContent=tr('Iniciar práctica','Start training');staticLabels.forEach(({m,es,en})=>m.userData.setText(tr(es,en)));keyTitle.userData.setText(tr('LLAVE','KEY'));parts.filter(p=>p.cameraLabel).forEach(p=>p.cameraLabel.userData.setText(tr('cámara','camera')));updateScenarioNote();updateSelected();drawMeter();updateMeterControls();}
function updateScenarioNote(){const code=$('scenario').value,variable=['F1','F6','F7','F8'].includes(code);$('segment').disabled=!variable;$('segmentLabel').style.opacity=variable?'1':'.4';$('scenarioNote').textContent=tr('Iniciar restaura las piezas y las mediciones. No se muestran respuestas ni puntuaciones.','Starting resets all parts and measurements. No answers or scores are shown.');}
$('scenario').addEventListener('change',updateScenarioNote);$('lang').onclick=()=>{lang=lang==='es'?'en':'es';updateLabels();};function openInstructor(){releaseDrag();$('instructor').showModal();}$('instructorHint').onclick=openInstructor;$('closeSetup').onclick=()=>$('instructor').close();$('scenarioForm').onsubmit=e=>{e.preventDefault();buildScenario($('scenario').value,$('segment').value);$('instructor').close();};
window.addEventListener('keydown',e=>{if($('instructor').open)return;if(e.key.toLowerCase()==='i'){e.preventDefault();openInstructor();}if(e.key==='Escape'){releaseDrag();restoreCamera();selected=null;updateSelected();}if(selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const sign=e.key==='ArrowLeft'||e.key==='ArrowDown'?-1:1;const threaded=selectedPorts(selected).some(p=>p.joint&&['circular','em'].includes(p.kind));if(!threaded)rotateSelected(e.shiftKey?'z':e.key==='ArrowUp'||e.key==='ArrowDown'?'x':'y',sign);}});
function paintScreen(part,state,time){if(state!=='spinner'&&part.lastState===state&&part.lastLang===lang)return;part.lastState=state;part.lastLang=lang;const c=part.screenCanvas,ctx=c.getContext('2d');ctx.fillStyle=state==='off'?'#080f13':'#112636';ctx.fillRect(0,0,c.width,c.height);if(state!=='off'){ctx.textAlign='center';if(state==='spinner'){ctx.lineWidth=10;ctx.strokeStyle='#425567';ctx.beginPath();ctx.arc(384,160,46,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#e6f2f5';ctx.beginPath();ctx.arc(384,160,46,time*2,time*2+Math.PI*1.35);ctx.stroke();ctx.fillStyle='#d7e3ed';ctx.font='25px Arial';ctx.fillText(tr('Espera mientras nos conectamos','Please wait while we connect'),384,282);ctx.fillText(tr('al Expansion Module','to the Expansion Module'),384,320);}else{ctx.fillStyle='#f0f4f6';ctx.font='bold 61px Arial';ctx.fillText('FLEET',384,178);ctx.fillStyle='#e8a464';ctx.font='36px Arial';ctx.fillText('iQ360',384,230);ctx.fillStyle='#b6c9d6';ctx.font='24px Arial';ctx.fillText(tr('Bienvenido','Welcome'),384,332);}}part.screenTexture.needsUpdate=true;}
let hitboxesVisible=false;const hitboxGroup=new T.Group();scene.add(hitboxGroup);const hitboxMap=new Map();$('hitboxes').onclick=()=>{hitboxesVisible=!hitboxesVisible;$('hitboxes').setAttribute('aria-pressed',String(hitboxesVisible));hitboxGroup.visible=hitboxesVisible;$('hitboxes').textContent=hitboxesVisible?tr('Ocultar hitboxes','Hide hitboxes'):tr('Mostrar hitboxes','Show hitboxes');};
function updateHitboxes(){hitboxGroup.visible=hitboxesVisible;if(!hitboxesVisible)return;for(const [m,h] of hitboxMap)if(!allColliders.includes(m)){h.geometry.dispose();h.material.dispose();hitboxGroup.remove(h);hitboxMap.delete(m);}for(const m of allColliders){let h=hitboxMap.get(m);if(!h){h=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(1,1,1)),new T.LineBasicMaterial({color:0x42e8df,depthTest:false,transparent:true,opacity:.8}));h.renderOrder=1000;hitboxGroup.add(h);hitboxMap.set(m,h);}m.updateWorldMatrix(true,false);h.matrixAutoUpdate=false;h.matrix.copy(m.matrixWorld).multiply(new T.Matrix4().makeTranslation(...(m.userData.solidCenter||V()).toArray())).multiply(new T.Matrix4().makeScale(...m.userData.solid.clone().multiplyScalar(2).toArray()));h.matrixWorldNeedsUpdate=true;}}
function cameraSafe(position){const sphere=new T.Sphere(position,.38);if(position.y<.25)return false;for(const m of allColliders){const obb=colliderOf(m);if(obb.intersectsSphere(sphere))return false;}return true;}
function ejectCamera(position){let safe=position.clone();for(let pass=0;pass<20&&!cameraSafe(safe);pass++){safe.y=Math.max(.45,safe.y);let moved=false;for(const m of allColliders){const obb=colliderOf(m);if(!obb.intersectsSphere(new T.Sphere(safe,.38)))continue;const inv=obb.rotation.clone().transpose(),local=safe.clone().sub(obb.center).applyMatrix3(inv),half=obb.halfSize.clone().addScalar(.40);let axis='x',dist=Infinity;for(const key of ['x','y','z']){const d=half[key]-Math.abs(local[key]);if(d<dist){dist=d;axis=key;}}local[axis]=(local[axis]>=0?1:-1)*half[axis];safe.copy(local.applyMatrix3(obb.rotation).add(obb.center));moved=true;}if(!moved)break;}if(!cameraSafe(safe))safe.set(12,13,22);return safe;}
function guardCamera(){const desired=camera.position.clone(),from=cameraSafe(lastCamera)?lastCamera.clone():ejectCamera(lastCamera),distance=desired.distanceTo(from);const steps=Math.max(1,Math.ceil(distance/.08));let safe=from.clone();for(let i=1;i<=steps;i++){const candidate=from.clone().lerp(desired,i/steps);if(!cameraSafe(candidate)){cameraMotion=null;break;}safe.copy(candidate);}camera.position.copy(safe);lastCamera.copy(safe);camera.lookAt(controls.target);}
let lastEval=0,states={screens:{},ems:{}};function animate(ms){requestAnimationFrame(animate);clock=ms/1000;controls.update();if(cameraMotion){const motion=cameraMotion,t=Math.min(1,(ms-motion.start)/motion.duration),s=t*t*(3-2*t);camera.position.lerpVectors(motion.from,motion.to,s);controls.target.lerpVectors(motion.startTarget,motion.target,s);camera.lookAt(controls.target);if(t>=1)cameraMotion=null;}guardCamera();if(drag&&cameraMotion){ray.setFromCamera(pointer,camera);const at=ray.ray.intersectPlane(plane,V());if(at)drag.offset=selectedEntity(selected).getWorldPosition(V()).sub(at);}
 if(ms-lastEval>90){states=circuit.evaluate();if(probes.length===2&&meterMode!=='off'&&meterResult!=='—'){const [a,b]=probes;const reading=meterMode==='voltage'?`${circuit.voltage(node(a.port,a.n),node(b.port,b.n)).toFixed(1)} V`:circuit.continuity(node(a.port,a.n),node(b.port,b.n))?tr('PASA','PASS'):tr('NO PASA','NO PASS');if(reading!==meterResult){meterResult=reading;drawMeter();}}lastEval=ms;}for(const p of parts){if(p.type==='screen')paintScreen(p,states.screens[p.id]||'off',clock);if(p.type==='em'){const s=states.ems[p.id];const on=s==='steady'||s==='blink'&&Math.sin(clock*Math.PI)>0;p.led.material.color.setHex(on?0x36e876:0x0c2118);p.led.material.emissiveIntensity=on?1.8:0;}}
 updateHitboxes();renderer.render(scene,camera);}
