const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'set_training_scenario',description:'Start a fresh MK3 training session using the instructor setup. Resets all physical parts and measurements.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(scenarios)},segment:{type:'string',enum:['upper','lower']}},required:['scenario','segment'],additionalProperties:false},execute(input){if(!input||!Object.hasOwn(scenarios,input.scenario)||!['upper','lower'].includes(input.segment))throw new Error('Invalid scenario or segment');buildScenario(input.scenario,input.segment);return{started:true};}});register({name:'read_hardware_observations',description:'Read only the currently observable MK3 screen and Expansion Module LED states. Does not identify faulty parts.',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{},additionalProperties:false},execute(){const state=circuit.evaluate();return{key:circuit.key,screens:Object.values(state.screens),statusLEDs:Object.values(state.ems),otherLEDs:'off',meter:meterMode==='off'?'off':meterResult};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
